/* =====================================================================
 *  ROLL & ASSIGN — Ability Score Generator
 *  D&D 5.5e (2024) · Foundry VTT v14 · ApplicationV2 (default styling)
 *
 *    • Rolls one ability at 1d4+14, two at 2d6+6, one at 4d6k3, two at 3d6
 *    • DRAG a value tile onto another ability to swap the two
 *    • Dice So Nice animation on the roll, if the module is installed
 *    • Totals all six scores and compares to the 2024 standard array (72)
 *        — total shown green if ≥ 72, red if < 72
 *    • Auto-posts the "Initial Roll Order" to chat on the first run
 *    • "Send to Chat" posts the arranged spread labeled "Final"; "Copy" → clipboard
 *    • No reroll, no reset — you roll once and arrange
 *
 *  HOW TO USE
 *    1. Create a new *Script* macro and paste this entire file in.
 *    2. Execute it — the six values are rolled (and animated) immediately.
 *    3. Drag value tiles between abilities to arrange them.
 *    4. Click "Send to Chat" / "Copy to Clipboard" to export.
 *
 *  The roll happens once.  Re-running the macro re-opens the SAME window
 *  with the same values (there is no reroll).  Close the window to discard
 *  them; the next run then rolls a fresh set.
 *
 *  Note: tile dragging uses native HTML5 drag-and-drop — mouse/desktop,
 *  not touch or keyboard.
 * ===================================================================== */

const { ApplicationV2 } = foundry.applications.api;

class RollAssignApp extends ApplicationV2 {

  static ABILITIES = [
    { key: "str", label: "Strength" },
    { key: "dex", label: "Dexterity" },
    { key: "con", label: "Constitution" },
    { key: "int", label: "Intelligence" },
    { key: "wis", label: "Wisdom" },
    { key: "cha", label: "Charisma" }
  ];

  /* The six ability rolls, in the order their dice appear in the combined roll.
   * `flat` is added to the kept dice; `label` is shown in the "Rolled As" column. */
  static ROLLS = [
    { formula: "1d4",    flat: 14, label: "1d4+14" },
    { formula: "2d6",    flat: 6,  label: "2d6+6"  },
    { formula: "2d6",    flat: 6,  label: "2d6+6"  },
    { formula: "4d6kh3", flat: 0,  label: "4d6k3"  },
    { formula: "3d6",    flat: 0,  label: "3d6"    },
    { formula: "3d6",    flat: 0,  label: "3d6"    }
  ];

  /* D&D 2024 standard array: 15, 14, 13, 12, 10, 8 = 72 */
  static STD_ARRAY_TOTAL = 72;

  static mod(score) { return Math.floor((score - 10) / 2); }
  static fmtMod(m) { return (m >= 0 ? "+" : "") + m; }
  static totalColor(total) { return total >= RollAssignApp.STD_ARRAY_TOTAL ? "#27ae60" : "#e74c3c"; }

  /* Roll the whole pool in ONE throw, animate via Dice So Nice if present,
   * then return six { total, detail } slots in ROLLS order. */
  static async rollPool() {
    const C = RollAssignApp;

    // ONE combined roll, so every die is part of a single throw.  Dice So Nice
    // drives one shared dice box — firing several showForRoll calls at once makes
    // them collide and nothing renders, so we animate the whole set together.
    const formula = C.ROLLS.map(r => r.flat ? `${r.formula} + ${r.flat}` : r.formula).join(" + ");
    const roll = await new Roll(formula).evaluate();

    if (game.dice3d) {
      try {
        await game.dice3d.showForRoll(roll, game.user, true);   // 3rd arg: show to all players
      } catch (err) {
        console.error("Dice So Nice | showForRoll failed:", err);
      }
    } else {
      ui.notifications?.info("Dice So Nice not detected — rolling without animation.");
    }

    // roll.dice holds only the DiceTerms (the flat +14 / +6 numbers are excluded),
    // in formula order — so it lines up 1:1 with C.ROLLS.
    return roll.dice.map((die, idx) => {
      const spec = C.ROLLS[idx];
      const kept = die.results.filter(d => d.active).map(d => d.result);
      const drop = die.results.filter(d => !d.active).map(d => d.result);
      const total = kept.reduce((s, v) => s + v, 0) + spec.flat;

      let detail;
      if (drop.length)        detail = `${spec.label}: ${kept.join(", ")} — drop ${drop.join(", ")}`;
      else if (spec.flat)     detail = `${spec.label}: ${kept.join(", ")} + ${spec.flat}`;
      else                    detail = `${spec.label}: ${kept.join(", ")}`;

      return { total, detail };
    });
  }

  static async _onSend() {
    await this._sendToChat("final");
  }

  static async _onCopy() {
    await this._copyToClipboard();
  }

  static DEFAULT_OPTIONS = {
    id: "roll-assign-abilities",
    tag: "div",
    window: {
      title: "Roll & Assign — D&D 5.5e",
      icon: "fa-solid fa-dice-d6",
      resizable: true
    },
    position: { width: 600, height: "auto" },
    actions: {
      send: this._onSend,
      copy: this._onCopy
    }
  };

  constructor(pool = [], options = {}) {
    super(options);
    this.pool = pool;            // six { total, detail } — fixed after the roll
    this.assign = {};            // abilityKey -> slot index (always a permutation)
    this._dragKey = null;        // ability the in-flight tile came from
    RollAssignApp.ABILITIES.forEach((a, i) => { this.assign[a.key] = i; });
  }

  /* Sum of all six rolled scores (constant for a given roll — arranging never changes it). */
  get total() {
    return this.pool.reduce((s, p) => s + (p?.total ?? 0), 0);
  }

  /* Drop the cached instance on close so the next run rolls a fresh set. */
  async close(options) {
    if (globalThis.__rollAssignApp === this) delete globalThis.__rollAssignApp;
    return super.close(options);
  }

  /* ---- rendering (manual; default chrome, minimal inline layout hints) ---- */
  async _renderHTML() {
    const root = document.createElement("div");
    root.innerHTML = this._buildHTML();
    return root;
  }

  _replaceHTML(result, content) {
    content.replaceChildren(result);
  }

  _onRender() {
    const root = this.element;
    for (const tile of root.querySelectorAll("[data-drag-key]")) {
      tile.addEventListener("dragstart", this._onDragStart.bind(this));
      tile.addEventListener("dragend", this._onDragEnd.bind(this));
    }
    for (const zone of root.querySelectorAll("[data-drop-key]")) {
      zone.addEventListener("dragover", this._onDragOver.bind(this));
      zone.addEventListener("dragleave", this._onDragLeave.bind(this));
      zone.addEventListener("drop", this._onDrop.bind(this));
    }
  }

  /* ---- drag & drop: dropping tile A onto ability B swaps their slots ---- */
  _onDragStart(event) {
    this._dragKey = event.currentTarget.dataset.dragKey;
    event.dataTransfer.setData("text/plain", this._dragKey);
    event.dataTransfer.effectAllowed = "move";
  }

  _onDragEnd() {
    this._dragKey = null;
    this._clearDropHighlights();
  }

  _onDragOver(event) {
    event.preventDefault();
    event.dataTransfer.dropEffect = "move";
    event.currentTarget.style.outline = "2px dashed var(--color-border-highlight, #ff6400)";
    event.currentTarget.style.outlineOffset = "-2px";
  }

  _onDragLeave(event) {
    event.currentTarget.style.outline = "";
    event.currentTarget.style.outlineOffset = "";
  }

  _onDrop(event) {
    event.preventDefault();
    const from = event.dataTransfer.getData("text/plain") || this._dragKey;
    const to = event.currentTarget.dataset.dropKey;
    this._clearDropHighlights();
    this._dragKey = null;
    if (!from || !to || from === to) return;
    const tmp = this.assign[from];
    this.assign[from] = this.assign[to];
    this.assign[to] = tmp;
    this.render();   // nothing transient to preserve, so a clean re-render is simplest
  }

  _clearDropHighlights() {
    if (!this.element) return;
    for (const z of this.element.querySelectorAll("[data-drop-key]")) {
      z.style.outline = "";
      z.style.outlineOffset = "";
    }
  }

  _tile(key, value) {
    return `<div draggable="true" data-drag-key="${key}" title="Drag onto another ability to swap"
      style="display:inline-block;min-width:2.4em;padding:0.35em 0.7em;border:1px solid var(--color-border-dark,#7a7971);border-radius:5px;background:rgba(127,127,127,0.12);cursor:grab;font-size:1.1em;font-weight:600;user-select:none;">${value}</div>`;
  }

  _buildHTML() {
    const C = RollAssignApp;

    const rows = C.ABILITIES.map(a => {
      const slot = this.assign[a.key];
      const score = this.pool[slot]?.total ?? 0;
      const detail = this.pool[slot]?.detail ?? "";
      return `
        <tr>
          <td>${a.label}</td>
          <td data-drop-key="${a.key}" style="text-align:center;padding:0.4em 0.6em;">${this._tile(a.key, score)}</td>
          <td style="text-align:center;">${C.fmtMod(C.mod(score))}</td>
          <td style="opacity:0.7;font-size:0.85em;">${detail}</td>
        </tr>`;
    }).join("");

    const total = this.total;
    const diff  = total - C.STD_ARRAY_TOTAL;
    const color = C.totalColor(total);

    return `
      <p style="margin:0 0 0.5em;">Drag a value tile onto another ability to swap the two values.</p>
      <p style="margin:0 0 0.75em;opacity:0.85;">Dice formulas: 1× 1d4+14 · 2× 2d6+6 · 1× 4d6k3 · 2× 3d6</p>
      <table style="width:100%;border-collapse:collapse;">
        <thead>
          <tr>
            <th style="text-align:left;">Attribute</th>
            <th>Ability Score</th>
            <th>Ability Modifier</th>
            <th style="text-align:left;">Rolled As</th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
      <div style="margin-top:0.75em;padding-top:0.6em;border-top:1px solid var(--color-border-dark,#7a7971);font-size:1.05em;">
        Total: <strong style="color:${color};font-size:1.2em;">${total}</strong>
        &nbsp;<span style="opacity:0.85;">vs. Standard Array (${C.STD_ARRAY_TOTAL})</span>
        &nbsp;<strong style="color:${color};">${diff >= 0 ? "+" : ""}${diff}</strong>
      </div>
      <div style="display:flex;justify-content:flex-end;gap:0.5em;margin-top:0.6em;">
        <button type="button" data-action="copy"><i class="fa-solid fa-copy"></i> Copy to Clipboard</button>
        <button type="button" data-action="send"><i class="fa-solid fa-comments"></i> Send to Chat</button>
      </div>`;
  }

  /* ---- plain-text copy ---- */
  _resultsText() {
    const C = RollAssignApp;
    const lines = C.ABILITIES.map(a => {
      const score = this.pool[this.assign[a.key]]?.total ?? 0;
      return `${a.label}: ${score} (${C.fmtMod(C.mod(score))})`;
    });
    const total = this.total;
    const diff  = total - C.STD_ARRAY_TOTAL;
    lines.push(`Total: ${total} (Standard Array ${C.STD_ARRAY_TOTAL}, ${diff >= 0 ? "+" : ""}${diff})`);
    return lines.join("\n");
  }

  async _copyToClipboard() {
    try {
      await game.clipboard.copyPlainText(this._resultsText());   // cross-browser; works over plain HTTP
      ui.notifications?.info("Ability scores copied to clipboard.");
    } catch (err) {
      console.error("Roll & Assign | clipboard copy failed:", err);
      ui.notifications?.warn("Couldn't copy to clipboard — see the console (F12).");
    }
  }

  /* ---- chat output ---- */
  async _sendToChat(phase = "final") {
    const C = RollAssignApp;
    const border = "1px solid rgba(0,0,0,0.1)";

    // Label the card by phase: the auto-post is the rolled order; the button is final.
    const PHASES = {
      initial: { text: "Initial Roll Order", bg: "#6b6b6b" },
      final:   { text: "Final",              bg: "#7a2e2e" }
    };
    const badge = PHASES[phase] ?? PHASES.final;

    const rows = C.ABILITIES.map(a => {
      const slot = this.assign[a.key];
      const score = this.pool[slot]?.total ?? 0;
      const detail = this.pool[slot]?.detail ?? "";
      return `<tr>
        <td style="padding:3px 8px;border-bottom:${border};">${a.key.toUpperCase()}</td>
        <td style="padding:3px 8px;text-align:center;font-weight:700;border-bottom:${border};">${score}</td>
        <td style="padding:3px 8px;text-align:center;border-bottom:${border};">${C.fmtMod(C.mod(score))}</td>
        <td style="padding:3px 8px;border-bottom:${border};opacity:0.75;font-size:0.9em;">${detail}</td>
      </tr>`;
    }).join("");

    const total = this.total;
    const diff  = total - C.STD_ARRAY_TOTAL;
    const color = C.totalColor(total);

    const content = `
      <div>
        <h3 style="margin:0 0 4px;padding-bottom:3px;border-bottom:2px solid #7a2e2e;">
          <i class="fa-solid fa-dice-d20"></i> Ability Scores
          <span style="display:inline-block;font-size:0.6em;font-weight:700;letter-spacing:0.04em;text-transform:uppercase;vertical-align:middle;margin-left:6px;padding:1px 8px;border-radius:10px;background:${badge.bg};color:#fff;">${badge.text}</span>
        </h3>
        <table style="width:100%;border-collapse:collapse;margin:4px 0;">
          <thead>
            <tr style="font-size:0.85em;white-space:nowrap;">
              <th style="text-align:left;padding:3px 8px;border-bottom:2px solid rgba(0,0,0,0.25);">Attribute</th>
              <th style="padding:3px 8px;border-bottom:2px solid rgba(0,0,0,0.25);">Score</th>
              <th style="padding:3px 8px;border-bottom:2px solid rgba(0,0,0,0.25);">Mod</th>
              <th style="text-align:left;padding:3px 8px;border-bottom:2px solid rgba(0,0,0,0.25);">Rolled As</th>
            </tr>
          </thead>
          <tbody>${rows}</tbody>
        </table>
        <p style="margin:6px 0 0;font-size:1.05em;">
          Total: <strong style="color:${color};">${total}</strong>
          &nbsp;vs. Standard Array (${C.STD_ARRAY_TOTAL})
          &nbsp;<strong style="color:${color};">${diff >= 0 ? "+" : ""}${diff}</strong>
        </p>
      </div>`;

    await ChatMessage.create({ speaker: ChatMessage.getSpeaker(), content });
  }
}

/* ===================================================================== *
 *  Launch — roll once, cache the instance for the session
 * ===================================================================== */
(async () => {
  let app = globalThis.__rollAssignApp;
  if (!(app instanceof RollAssignApp)) {
    const pool = await RollAssignApp.rollPool();
    app = globalThis.__rollAssignApp = new RollAssignApp(pool);
    await app._sendToChat("initial");   // auto-post the rolled order, labeled "Initial Roll Order"
  }
  app.render(true);
})();
